mapper.select:
SELECT cr.id, cr.partner_id AS partnerId, cr.cert_type AS certType, cr.request_key AS requestKey, cr.provider_code AS providerCode, cr.provider_seq_no AS providerSeqNo, cr.code, cr.message, cr.state, cr.charged, cr.request_params AS requestParams, cr.response_body AS responseBody, cr.create_time AS createTime, p.name AS partnerName, p.mobile AS partnerMobile FROM partner_certification_record cr LEFT JOIN partner p ON cr.partner_id = p.id AND p.deleted = 0 WHERE cr.deleted = 0
AND cr.partner_id = #{reqVO.partnerId}
AND cr.cert_type = #{reqVO.certType}
AND cr.provider_code = #{reqVO.providerCode}
AND cr.state = #{reqVO.state}
AND cr.provider_seq_no = #{reqVO.providerSeqNo}
AND p.name LIKE CONCAT('%', #{reqVO.partnerName}, '%')
AND p.mobile = #{reqVO.partnerMobile}
AND cr.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY cr.id DESC
